'use strict';
const { test } = require('node:test'), a = require('node:assert/strict'), C = require('./core');
const customer = { authenticated: true, userId: 'user_demo', role: 'customer', caseIds: ['case_demo'] };
const staff = { ...customer, userId: 'staff_demo', role: 'staff' };
const event = (s, action = 'report', eventId = 'e1', itemId = 'I01') => ({ eventId, caseId: s.caseId, itemId, version: s.version, action });
const update = (s, action, principal = customer, id = 'e'+s.version, item = 'I01') => {const r = C.transition(s, event(s, action, id, item), principal); a.equal(r.code, 'UPDATED'); return r.state;};
test('自報不升級核對；純函式不修改輸入', () => {const s=C.createState(), before=JSON.stringify(s), n=update(s,'report');a.equal(n.items[0].reported,true);a.equal(n.items[0].verified,false);a.equal(JSON.stringify(s),before);a.equal(C.status(n.items[0]),'已提供（您自行標記）／專員尚未確認');});
test('客戶不能改任何承辦狀態', () => {const s=C.createState();for(const action of ['verify','unverify','approveNotApplicable','rejectNotApplicable','applicable'])a.equal(C.transition(s,event(s,action),customer).code,'STAFF_REQUIRED');});
test('承辦不能冒充客戶自報',()=>{const s=C.createState();for(const action of ['report','unreport','requestNotApplicable','withdrawNotApplicable'])a.equal(C.transition(s,event(s,action),staff).code,'CUSTOMER_REQUIRED');});
test('客戶反悔不撤銷承辦核對',()=>{let n=update(C.createState(),'report');n=update(n,'verify',staff);n=update(n,'unreport');a.equal(n.items[0].reported,false);a.equal(n.items[0].verified,true);});
test('不同user隔離，包括同case授權',()=>{const s=C.createState();a.equal(C.transition(s,event(s),{...customer,userId:'other'}).code,'USER_MISMATCH');a.equal(C.transition(s,event(s),{...customer,role:'admin'}).code,'USER_MISMATCH');});
test('不同case隔離且兩個state不互相變動',()=>{const s=C.createState(),other=C.createState('other','other_user'),before=JSON.stringify(other);a.equal(C.transition(s,{...event(s),caseId:'other'},customer).code,'CASE_MISMATCH');a.equal(C.transition(other,event(s),{...customer,userId:'other_user',caseIds:['other']}).code,'CASE_MISMATCH');update(s,'report');a.equal(JSON.stringify(other),before);});
test('承辦也必須具備指定case授權',()=>{const s=C.createState();a.equal(C.transition(s,event(s,'verify'),{...staff,caseIds:['other']}).code,'AUTH_REQUIRED');});
test('身份驗證未設定、失敗、丟出例外均拒絕',async()=>{const s=C.createState();for(const verify of [undefined,async()=>null,async()=>({...customer,authenticated:false}),async()=>{throw Error('fail');}])a.equal((await C.backend(s,event(s),verify)).code,'AUTH_REQUIRED');a.equal((await C.backend(s,event(s),async()=>customer)).code,'UPDATED');});
test('舊版本和未來版本拒絕，仍可產生最新版Flex',()=>{const s=C.createState(),n=update(s,'report');a.equal(C.transition(n,event(s,'unreport','e2'),customer).code,'STALE_VERSION');a.equal(C.transition(n,{...event(n,'report','future'),version:99},customer).code,'STALE_VERSION');a.ok(JSON.stringify(C.flex(n)).includes('v2'));});
test('相同event重播不重複更新，版本已變也回冪等結果',()=>{const s=C.createState(),e=event(s),n=C.transition(s,e,customer).state,r=C.transition(n,e,customer);a.equal(r.code,'DUPLICATE_EVENT');a.equal(r.state,n);a.equal(n.version,2);});
test('同版本不同event連點只接受第一次',()=>{const s=C.createState(),n=update(s,'report');for(const id of ['e2','e3'])a.equal(C.transition(n,event(s,'report',id),customer).code,'STALE_VERSION');a.equal(n.events.length,1);});
test('未知文件ID、已知但不在此個案的文件均拒絕',()=>{const s=C.createState();for(const id of ['UNKNOWN','A12'])a.equal(C.transition(s,event(s,'report','e1',id),customer).code,'UNKNOWN_ITEM');});
test('申請不適用不移除文件；承辦核定才移除',()=>{let n=update(C.createState(),'requestNotApplicable');a.equal(n.items[0].applicable,true);a.equal(n.items[0].notApplicableRequested,true);a.equal(C.progress(n).total,1);n=update(n,'approveNotApplicable',staff);a.equal(n.items[0].applicable,false);a.equal(C.progress(n).total,0);a.equal(C.transition(n,event(n,'report','new_event'),customer).code,'NOT_APPLICABLE');});
test('承辦無待核定申請不可直接核定，客戶可撤回申請',()=>{let s=C.createState();a.equal(C.transition(s,event(s,'approveNotApplicable'),staff).code,'NO_PENDING_REQUEST');s=update(s,'requestNotApplicable');s=update(s,'withdrawNotApplicable');a.equal(s.items[0].notApplicableRequested,false);a.equal(s.items[0].applicable,true);});
test('承辦可否准或恢復適用，客戶不能恢復',()=>{let s=update(C.createState(),'requestNotApplicable');s=update(s,'rejectNotApplicable',staff);a.equal(s.items[0].notApplicableRequested,false);s=update(s,'requestNotApplicable');s=update(s,'approveNotApplicable',staff);a.equal(C.transition(s,event(s,'applicable'),customer).code,'STAFF_REQUIRED');s=update(s,'applicable',staff);a.equal(s.items[0].applicable,true);});
test('銀行額外需求需承辦確認，不預設戶籍／第二證件或角色文件',()=>{const ids=C.resolveItems();a.deepEqual(ids,['I01']);for(const id of ['A01','A02','A03','A05','A06','A07','A08','A11','A12','A13','A14','C01'])a.ok(!ids.includes(id));a.throws(()=>C.resolveItems({bankRequired:['A02']}));const custom=C.resolveItems({purpose:'refinance',incomes:['self'],bankRequired:['A08','A02','A13'],assets:['S01'],closing:['C04'],bankConfirmed:true});a.deepEqual(custom,['I03','A08','A02','A13','S01','C04']);});
test('收入分支与混合配置：只計實際來源，不全算必交或另算混合分類',()=>{const incomes=['salary','cash','self','professional','retired','rental'];for(let i=0;i<incomes.length;i++)a.deepEqual(C.resolveItems({incomes:[incomes[i]]}),['I0'+(i+1)]);a.deepEqual(C.resolveItems({incomes:['salary','rental']}),['I01','I06']);a.throws(()=>C.resolveItems({incomes:['mixed']}));});
test('後段及補充資產不計主要完成率',()=>{const s=C.createState('case_demo','user_demo',C.resolveItems({closing:['C01','C02','C03','C04','C05'],assets:['S01'],bankConfirmed:true}));a.equal(C.progress(s).total,1);a.equal(C.progress(s).pending,1);});
test('輸入校驗：額外敏感欄位、不合法ID、狀態、action、版本',()=>{const s=C.createState();for(const bad of [{...event(s),account:'123'},{...event(s),version:NaN},{...event(s),version:0},{...event(s),version:1.5},{...event(s),action:'cancel'},{...event(s),eventId:'<script>'},null])a.equal(C.transition(s,bad,customer).code,'INVALID_INPUT');a.equal(C.transition({...s,bankAccount:'123'},event(s),customer).code,'INVALID_STATE');a.equal(C.transition({...s,items:[null]},event(s),customer).code,'INVALID_STATE');a.throws(()=>C.createState('x'.repeat(65)));a.throws(()=>C.createState('c','u',['I01','I01']));a.throws(()=>C.resolveItems({months:6}));a.throws(()=>C.resolveItems({incomes:['unknown']}));a.throws(()=>C.resolveItems({roles:['spouse']}));});
test('postback roundtrip與嚴格欄位校驗',()=>{const s=C.createState();a.deepEqual(C.parsePostback(C.postback(s,s.items[0],'report'),'e1'),event(s));for(const data of ['c=x&c=y&i=A01&a=report&v=1','c=x&i=A01&a=report&v=0','c=x&i=A01&a=verify&v=1&staff=true','c=%3Cscript%3E&i=A01&a=report&v=1','c=x&i=A01&a=report&v=9007199254740992','x'.repeat(301)])a.throws(()=>C.parsePostback(data,'e1'));a.throws(()=>C.postback(s,{id:'UNKNOWN'},'report'));});
function validateMessage(message, expectedItems) {
 a.equal(message.type,'flex');a.ok(message.altText.length<=400);a.ok(!message.altText.includes('case_'));const bubbles=message.contents.type==='carousel'?message.contents.contents:[message.contents];a.ok(bubbles.length<=12);a.ok(Buffer.byteLength(JSON.stringify(message.contents))<=50000);let documents=0;
 for(const bubble of bubbles){a.equal(bubble.type,'bubble');a.ok(Buffer.byteLength(JSON.stringify(bubble))<=30000);a.equal(bubble.body.type,'box');a.equal(bubble.body.layout,'vertical');const rows=bubble.body.contents.filter(x=>x.type==='box');a.ok(rows.length<=4);documents+=rows.length;for(const row of rows){for(const child of row.contents){if(child.type==='text'){a.equal(child.wrap,true);a.ok(child.text.length>0);}else{a.equal(child.type,'button');a.equal(child.action.type,'postback');a.ok(child.action.label.length<=20);a.ok(child.action.data.length<=300);a.ok(C.parsePostback(child.action.data,'event_test'));}}}}
 a.equal(documents,expectedItems);return bubbles;
}
test('一般財力清單一bubble，沒有公司文件或分類重複計件',()=>{const s=C.createState(),f=C.flex(s);a.equal(validateMessage(f,1).length,1);a.match(JSON.stringify(f),/房貸財力資料/);});
test('長清單26客戶文件分7頁，符合限制及狀態文案',()=>{const s=C.createState('case_demo','user_demo',C.customerCatalog.map(d=>d.id)),f=C.flex(s);a.equal(validateMessage(f,26).length,7);a.match(JSON.stringify(f),/後段通知，不算初次缺件/);let n=update(s,'report');a.match(JSON.stringify(C.flex(n)),/已提供（您自行標記）／專員尚未確認/);n=update(n,'requestNotApplicable');a.match(JSON.stringify(C.flex(n)),/已申請不適用／待承辦核定/);});
test('最長opaque ID與最大安全版本仍符合postback限制',()=>{const s=C.createState('c'.repeat(64),'u'.repeat(64));s.version=Number.MAX_SAFE_INTEGER;validateMessage(C.flex(s),1);a.equal(C.transition(s,event(s),{...customer,userId:s.userId,caseIds:[s.caseId]}).code,'VERSION_EXHAUSTED');});
test('輸出狀態只含opaque ID與旗標、事件版本，不含敏感資料欄位',()=>{const s=update(C.createState(),'report');a.deepEqual(Object.keys(s).sort(),['caseId','companyItems','events','items','userId','version']);a.deepEqual(Object.keys(s.items[0]).sort(),['applicable','id','notApplicableRequested','reported','verified']);a.deepEqual(Object.keys(s.companyItems[0]).sort(),['id','submitted']);a.equal(C.sources.checkedOn,'2026-10-06');});
test('公司負責不等於已送；公司文件不入客戶清單／分母／Flex',()=>{const s=C.createState();a.deepEqual(s.companyItems.map(i=>i.id),['A01','A06','A07']);a.ok(s.companyItems.every(i=>!i.submitted));a.equal(C.progress(s).total,1);const json=JSON.stringify(C.flex(s));for(const id of ['A01','A06','A07']){a.ok(!s.items.some(i=>i.id===id));a.ok(!json.includes(id));}a.throws(()=>C.createState('c','u',['A01']));});
test('客戶不能更動公司送銀行狀態或以自報冒充送件',()=>{const s=C.createState();for(const action of ['companySubmit','companyUnsubmit'])a.equal(C.transition(s,event(s,action,'company_event','A01'),customer).code,'STAFF_REQUIRED');for(const action of ['report','unreport','requestNotApplicable'])a.equal(C.transition(s,event(s,action,'company_event','A01'),customer).code,'COMPANY_ITEM');a.ok(s.companyItems.every(i=>!i.submitted));});
test('獨立承辦示範可記錄公司送件，仍不改客戶自報或完成率',()=>{const s=C.createState(),p=C.progress(s),n=update(s,'companySubmit',staff,'company_event','A01');a.equal(n.companyItems[0].submitted,true);a.deepEqual(n.items,s.items);a.deepEqual(C.progress(n),p);a.equal(C.transition(n,event(s,'companySubmit','company_event','A01'),staff).code,'DUPLICATE_EVENT');a.equal(C.transition(n,event(s,'companySubmit','old_company_event','A06'),staff).code,'STALE_VERSION');a.equal(C.transition(n,event(n,'companySubmit','unknown_company','I01'),staff).code,'UNKNOWN_COMPANY_ITEM');});
test('自營401／403／405按實際適用配置，一次僅一種；未確認則不展開',()=>{a.deepEqual(C.resolveItems({incomes:['self']}),['I03']);for(const taxForm of ['401','403','405']){a.throws(()=>C.resolveItems({incomes:['self'],taxForm}));const ids=C.resolveItems({incomes:['self'],taxForm,bankConfirmed:true});a.deepEqual(ids,['T'+taxForm]);a.equal(C.progress(C.createState('case_demo','user_demo',ids)).total,1);}a.throws(()=>C.resolveItems({incomes:['salary'],taxForm:'401',bankConfirmed:true}));});
test('補充存款／定存／股票／基金／保單需用才選，不全部必交',()=>{a.ok(!C.resolveItems().some(id=>id.startsWith('S')));for(const id of ['S01','S02','S03','S04','S05']){a.throws(()=>C.resolveItems({assets:[id]}));const ids=C.resolveItems({assets:[id],bankConfirmed:true});a.deepEqual(ids,['I01',id]);a.equal(C.progress(C.createState('case_demo','user_demo',ids)).total,1);}});
